import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long N = Long.parseLong(input[0]);
        long M = Long.parseLong(input[1]);
        long L = Long.parseLong(input[2]);
        long R = Long.parseLong(input[3]);

        long total = N * M;
        BigInteger totalExp = BigInteger.valueOf(total);
        BigInteger rangeSize = BigInteger.valueOf(R - L + 1);
        BigInteger mod = BigInteger.valueOf(MOD);

        if ((N * M) % 2 != 0) {
            long res = rangeSize.modPow(totalExp, mod).longValue();
            System.out.println((res + MOD) % MOD);
        } else {
            long res = rangeSize.modPow(totalExp, mod).longValue();
            if ((R - L) % 2 == 0) {
                res++;
            }
            long invTwo = power(2, MOD - 2, MOD);
            res = (res * invTwo) % MOD;
            System.out.println(res);
        }
    }

    public static long power(long base, long exp, long p) {
        long result = 1L;
        base %= p;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % p;
            }
            exp >>= 1;
            base = (base * base) % p;
        }
        return result;
    }
}
